0, ly = 0; ctx.moveTo(lx, ly); for(let j=0; j<8; j++) { lx += (Math.random()-0.5)*90; ly += 75; ctx.lineTo(lx, ly); } ctx.stroke(); ctx.shadowBlur = 0; ctx.restore(); ctx.save(); ctx.translate(camera.x, camera.y); ctx.fillStyle = 'rgba(255, 255, 255, 0.12)'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); ctx.restore(); } ctx.restore(); } drawBossSprite(ctx, e, stageId); const curT = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : (state.bossVulgarityTimer > 0 ? state.bossLastVulgarity : null); if (curT) { ctx.save(); ctx.font = 'bold 12px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 6; ctx.textAlign = 'center'; ctx.fillText(curT, e.pos.x + e.width / 2, e.pos.y - 30); ctx.restore(); } } else { if (e.enemyType === 'shield') { ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height); if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.lineWidth = 2; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); } } else if (e.id.startsWith('rusher')) { ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } else if (e.enemyType === 'flyer' && e.width > 60) { ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); } else { ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } } if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); } if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); } ctx.restore(); });
    if (status !== GameStatus.LEVEL_INTRO || state.introTimer >= 80) { drawPlayer(ctx, player); if (state.playerLastVulgarity && state.playerVulgarityTimer > 0) { ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore(); } }
    projectiles.forEach(p => { if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); } else if (p.isShrapnel) { ctx.fillStyle = '#757575'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = 'black'; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); } else if (p.isPoop) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.45); ctx.fillStyle = '#5D4037'; ctx.beginPath(); const r = p.height / 2; ctx.moveTo(-p.width/2 + r, -p.height/2); ctx.lineTo(p.width/2 - r, -p.height/2); ctx.arc(p.width/2 - r, 0, r, -Math.PI/2, Math.PI/2); ctx.lineTo(-p.width/2 + r, p.height/2); ctx.arc(-p.width/2 + r, 0, r, Math.PI/2, -Math.PI/2); ctx.fill(); ctx.strokeStyle = '#3E2723'; ctx.lineWidth = 2.5; ctx.stroke(); ctx.fillStyle = '#FFEB3B'; ctx.fillRect(-p.width/3.5, -p.height/5, 4, 4); ctx.fillRect(p.width/8, p.height/4, 3, 3); ctx.fillRect(p.width/4, -p.height/6, 3, 3); ctx.restore(); } else { ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } });
