    damageNumbers.forEach(d => { ctx.save(); const alpha = d.life / d.maxLife; ctx.globalAlpha = alpha; ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`; ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF'); ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY)) { ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
