};

const BOSS_THRESHOLDS: Record<string, { [key: number]: string }> = {
  'Artie Avalanche': {
    75: "IS IT GETTING WARM IN HERE? NO MATTER.",
    50: "YOU'RE CHIPPING AWAY AT PERFECTION!",
    25: "I'M MELTING... NO! REFREEZE EVERYTHING!",
    0: "FINALLY... THE SILENCE OF THE VOID."
  },
  'Victor Volcano': {
    75: "A MERE SPARK! I AM THE FURNACE!",
