    if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) return 150;
    const isWeak = checkIsWeakness(p);
    return isWeak ? 100 : BULLET_DAMAGE;
  };

  const update = useCallback(() => {
    const state = gameStateRef.current;
    const { player, enemies, projectiles, blocks, pickups, damageNumbers } = state;
    state.frame++;
    if (state.screenShakeTimer > 0) state.screenShakeTimer--;

    if (state.deathTimer > 0) {
        state.deathTimer--;
        if (state.deathTimer === 0) respawn();
        state.particles = state.particles.filter(p => { 
          if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; }
          return p.life > 0; 
        });
        return;
    }

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      state.screenShakeTimer = 5; 
      if (state.frame % 3 === 0) {
        spawnDeathShower(state.bossExplosionPos, (Math.random() - 0.5) * 4, 15.0, true, 180);
        spawnExplosion(state.bossExplosionPos, PARTICLE_PALETTES.FIRE[Math.floor(Math.random() * PARTICLE_PALETTES.FIRE.length)], 10, (Math.random() - 0.5) * 15, 60);
      } 
      state.particles = state.particles.filter(p => { 
          if (p.isStuck) return true;
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
          if (p.isBossGore) {
            p.vel.y += 0.35; 
            for (const b of blocks) {
                if (b.type === 'pit') continue;
                if (p.pos.x > b.x && p.pos.x < b.x + b.w && p.pos.y > b.y && p.pos.y < b.y + b.h) {
                    p.vel.x = 0; p.vel.y = 0; p.isStuck = true; break;
                }
            }
          }
          if (!p.isStuck) p.life--; 
          return p.life > 0; 
      });
      if (state.bossExplosionTimer <= 0) { onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0; }
      return; 
    }

    if (status === GameStatus.PAUSED) return;

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; 
        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        state.camera.x = baseStartX; 
        state.player.facing = 1; 
        if (state.introTimer === 30 && !jumpToBossEnabled) speakIntroLine(stageId); 
        if (state.introTimer < 80) { state.player.pos.x = baseStartX - 150; } 
        else {
            if (state.introTimer === 80) { playGlassShatterSound(); spawnGlassShatter({ x: baseStartX, y: 450 }); }
            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = baseStartX - 100 + (t * 250);
            const peakHeight = 250; const groundY = 486; const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;
            if (state.introTimer >= 80 + jumpDuration) { state.player.pos.y = groundY; state.player.pos.x = baseStartX + 150; state.player.vel = { x: 0, y: 0 }; onIntroComplete(); }
        }
        state.particles = state.particles.filter(p => { if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } return p.life > 0; });
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        const targetCameraX = BOSS_DOOR_X; const targetPlayerX = targetCameraX + 150; const glideSpeed = 4; 
        if (state.doorState === 'opening') { state.doorOpenAmount += 5; if (state.doorOpenAmount >= 150) { state.doorOpenAmount = 150; state.doorState = 'open'; } } 
        else if (state.doorState === 'open') { if (state.camera.x < targetCameraX) state.camera.x = Math.min(targetCameraX, state.camera.x + glideSpeed); if (player.pos.x < targetPlayerX) player.pos.x = Math.min(targetPlayerX, player.pos.x + glideSpeed); if (state.camera.x >= targetCameraX && player.pos.x >= targetPlayerX) state.doorState = 'closing'; } 
        else if (state.doorState === 'closing') { state.doorOpenAmount -= 5; if (state.doorOpenAmount <= 0) { state.doorOpenAmount = 0; state.doorState = 'done'; player.isCharging = false; player.isUppercutting = false; onBossEncounter(); } }
        player.pos.y += (486 - player.pos.y) * 0.05; player.vel = { x: 0, y: 0 }; player.facing = 1; state.projectiles = []; return;
    }

    if (status !== GameStatus.PLAYING) { if (status === GameStatus.BOSS_INTRO) state.arenaLocked = false; return; }
    if (player.pos.x >= BOSS_DOOR_X && state.doorState === 'done') state.arenaLocked = true;

    if (state.victoryString) {
      state.particles = state.particles.filter(p => { if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } return p.life > 0; });
      if (state.victoryString.length < 7) {
