    particles.forEach(p => { ctx.save(); if (!p.isStuck) ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; else ctx.globalAlpha = 0.85; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore(); });
    damageNumbers.forEach(d => { ctx.save(); const alpha = d.life / d.maxLife; ctx.globalAlpha = alpha; ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`; ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF'); ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY)) { ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, currentWeapon, invincibilityEnabled, jumpToBossEnabled, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { 
        if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) { 
            gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0; gameStateRef.current.particles = []; gameStateRef.current.projectiles = []; gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 }; gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH; gameStateRef.current.player.killSatisfactionTimer = 0; gameStateRef.current.player.bossKillSatisfactionTimer = 0; gameStateRef.current.player.invincibilityTimer = 0; gameStateRef.current.player.pushbackTimer = 0; gameStateRef.current.player.isCharging = false; gameStateRef.current.player.isUppercutting = false; gameStateRef.current.playerStunTimer = 0; createLevel(); gameStateRef.current.frame = 1; 
        } 
        frameId = window.requestAnimationFrame(loop); 
    } 
    else { 
        const s = gameStateRef.current;
        s.victoryString = ""; s.postVictoryTimer = 0; s.bossExplosionTimer = 0; s.introTimer = 0; s.enemies = []; s.particles = []; s.projectiles = []; s.blocks = []; s.camera = { x: 0, y: 0 }; s.playerLastVulgarity = ""; s.playerVulgarityTimer = 0; s.bossLastVulgarity = ""; s.bossVulgarityTimer = 0; s.bossVolcanoes = []; s.bossVolcanoTelegraphs = []; s.bossPoopTelegraphs = []; s.bossSteamExplosions = []; s.victorWallSide = 0; s.tsunamiActive = false; s.screenShakeTimer = 0; s.ernieVibrationTimer = 0; s.frame = 0;
        draw(); 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

